	testRule(t, "struct_tag_user_options", &rule.StructTagRule{}, &lint.RuleConfig{
		Arguments: []any{
			"json,inline,outline",
			"bson,gnu",
			"url,myURLOption",
			"datastore,myDatastoreOption",
			"mapstructure,myMapstructureOption",
			"validate,displayName",
			"toml,unknown",
			"spanner,mySpannerOption",
		},
	})
}

